
.panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  font-weight: 700;
  font-size: 14px;
  color: var(--c-accent-warm);
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}

.rival-stats {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.stat-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--c-text-label);
}
.stat-val {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--c-text-primary);
}

.stat-bar {
  height: 6px;
  border-radius: 3px;
  background: var(--c-bar-bg);
  overflow: hidden;
}
.stat-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;
}
.fill-rival {
  background: linear-gradient(90deg, #e17055, #d63031);
}

.computed-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.computed-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 8px;
  background: var(--c-bg-section);
  border-radius: 6px;
  border: 1px solid var(--c-border);
}
.computed-label {
  font-size: 11px;
  color: var(--c-text-secondary);
}
.computed-val {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 16px;
  color: var(--c-text-primary);
}
.highlight-danger {
  color: var(--c-danger) !important;
}
.highlight-warn {
  color: var(--c-accent-gold) !important;
}

.skills-section {
  margin-top: 4px;
}
.skills-label {
  font-size: 12px;
  color: var(--c-text-label);
  margin-bottom: 6px;
}
.skills-list {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.skill-tag {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 12px;
  background: rgba(225, 112, 85, 0.12);
  border: 1px solid rgba(225, 112, 85, 0.25);
  color: var(--c-accent-warm);
}
