
.panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.empty-state {
  text-align: center;
  padding: 24px;
  color: var(--c-text-secondary);
  font-style: italic;
}

.char-selector {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.char-btn {
  padding: 4px 12px;
  border-radius: 4px;
  background: var(--c-bg-section);
  border: 1px solid var(--c-border);
  color: var(--c-text-secondary);
  font-family: var(--font-main);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s;
  &:hover {
    border-color: var(--c-accent-rose);
    color: var(--c-text-primary);
  }
  &.active {
    background: rgba(232, 62, 140, 0.15);
    border-color: var(--c-accent-pink);
    color: var(--c-accent-rose);
  }
}

.char-detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.char-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}
.char-name {
  font-weight: 700;
  font-size: 15px;
  color: var(--c-accent-rose);
}
.char-stage {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 10px;
  background: rgba(155, 89, 182, 0.15);
  color: var(--c-accent-purple);
  border: 1px solid rgba(155, 89, 182, 0.25);
}

.stat-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.stat-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--c-text-label);
}
.stat-val {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 13px;
  color: var(--c-text-primary);
}

.stat-bar {
  height: 6px;
  border-radius: 3px;
  background: var(--c-bar-bg);
  overflow: hidden;
}
.stat-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.4s ease;
}
.fill-pink {
  background: linear-gradient(90deg, #e83e8c, #fd79a8);
}
.fill-cyan {
  background: linear-gradient(90deg, #00cec9, #81ecec);
}
.fill-purple {
  background: linear-gradient(90deg, #6c5ce7, #a29bfe);
}
.fill-warm {
  background: linear-gradient(90deg, #e17055, #fab1a0);
}
.fill-danger {
  background: linear-gradient(90deg, #d63031, #ff7675);
}

.stat-row-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}
.mini-stat {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 8px;
  background: var(--c-bg-section);
  border-radius: 4px;
  border: 1px solid var(--c-border);
  font-size: 11px;
}
.mini-label {
  color: var(--c-text-secondary);
}
.mini-val {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--c-text-primary);
}
.val-danger {
  color: var(--c-danger) !important;
}
.val-warn {
  color: var(--c-accent-gold) !important;
}

.info-row {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.info-tag {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--c-bg-section);
  border: 1px solid var(--c-border);
  color: var(--c-text-secondary);
}
